1	/**
2	 * IMU 数据管理模块
3	 * 负责加速度计和陀螺仪数据的采集、同步和缓冲
4	 */
5	
6	import sensor from '@system.sensor'
7	import { SAMPLING_CONFIG, DEFAULT_THRESHOLDS } from './constants'
8	
9	class IMUManager {
10	  constructor() {
11	    this.isRunning = false
12	    this.accelData = { x: 0, y: 0, z: 0, timestamp: 0 }
13	    this.gyroData = { x: 0, y: 0, z: 0, timestamp: 0 }
14	    this.buffer = []
15	    this.maxBufferSize = SAMPLING_CONFIG.BUFFER_SIZE
16	    this.listeners = []
17	  }
18	
19	  /**
20	   * 订阅加速度计数据
21	   */
22	  subscribeAccelerometer() {
23	    sensor.subscribeAccelerometer({
24	      interval: SAMPLING_CONFIG.INTERVAL,
25	      callback: (data) => {
26	        this.accelData = {
27	          x: data.x,
28	          y: data.y,
29	          z: data.z,
30	          timestamp: Date.now()
31	        }
32	        this.syncData()
33	      },
34	      fail: (data, code) => {
35	        console.error(`加速度计订阅失败: ${code}`)
36	      }
37	    })
38	  }
39	
40	  /**
41	   * 订阅陀螺仪数据
42	   */
43	  subscribeGyroscope() {
44	    sensor.subscribeGyroscope({
45	      interval: SAMPLING_CONFIG.INTERVAL,
46	      callback: (data) => {
47	        this.gyroData = {
48	          x: data.x,
49	          y: data.y,
50	          z: data.z,
51	          timestamp: Date.now()
52	        }
53	        this.syncData()
54	      },
55	      fail: (data, code) => {
56	        console.error(`陀螺仪订阅失败: ${code}`)
57	      }
58	    })
59	  }
60	
61	  /**
62	   * 数据同步 - 将加速度和角速度数据合并
63	   */
64	  syncData() {
65	    // 确保两个传感器都有数据
66	    if (this.accelData.timestamp === 0 || this.gyroData.timestamp === 0) {
67	      return
68	    }
69	
70	    const syncData = {
71	      accel: { ...this.accelData },
72	      gyro: { ...this.gyroData },
73	      timestamp: Date.now()
74	    }
75	
76	    // 添加到缓冲区
77	    this.buffer.push(syncData)
78	
79	    // 缓冲区满时移除最早的数据
80	    if (this.buffer.length > this.maxBufferSize) {
81	      this.buffer.shift()
82	    }
83	
84	    // 通知监听器
85	    this.notifyListeners(syncData)
86	  }
87	
88	  /**
89	   * 启动 IMU 数据采集
90	   */
91	  start() {
92	    if (this.isRunning) {
93	      console.log('IMU 已在运行中')
94	      return
95	    }
96	
97	    this.isRunning = true
98	    this.buffer = []
99	    this.subscribeAccelerometer()
100	    this.subscribeGyroscope()
101	    console.log('IMU 数据采集已启动')
102	  }
103	
104	  /**
105	   * 停止 IMU 数据采集
106	   */
107	  stop() {
108	    if (!this.isRunning) {
109	      return
110	    }
111	
112	    this.isRunning = false
113	    sensor.unsubscribeAccelerometer()
114	    sensor.unsubscribeGyroscope()
115	    console.log('IMU 数据采集已停止')
116	  }
117	
118	  /**
119	   * 获取当前数据
120	   */
121	  getCurrentData() {
122	    return {
123	      accel: { ...this.accelData },
124	      gyro: { ...this.gyroData }
125	    }
126	  }
127	
128	  /**
129	   * 获取缓冲区数据
130	   */
131	  getBuffer() {
132	    return [...this.buffer]
133	  }
134	
135	  /**
136	   * 清空缓冲区
137	   */
138	  clearBuffer() {
139	    this.buffer = []
140	  }
141	
142	  /**
143	   * 添加数据监听器
144	   */
145	  addListener(callback) {
146	    this.listeners.push(callback)
147	  }
148	
149	  /**
150	   * 移除数据监听器
151	   */
152	  removeListener(callback) {
153	    this.listeners = this.listeners.filter(cb => cb !== callback)
154	  }
155	
156	  /**
157	   * 通知所有监听器
158	   */
159	  notifyListeners(data) {
160	    this.listeners.forEach(cb => {
161	      try {
162	        cb(data)
163	      } catch (e) {
164	        console.error('监听器回调错误:', e)
165	      }
166	    })
167	  }
168	
169	  /**
170	   * 计算加速度幅值
171	   */
172	  getAccelMagnitude(accel) {
173	    return Math.sqrt(accel.x * accel.x + accel.y * accel.y + accel.z * accel.z)
174	  }
175	
176	  /**
177	   * 计算角速度幅值
178	   */
179	  getGyroMagnitude(gyro) {
180	    return Math.sqrt(gyro.x * gyro.x + gyro.y * gyro.y + gyro.z * gyro.z)
181	  }
182	}
183	
184	// 导出单例
185	export default new IMUManager()
